-- Dữ liệu để xem thử các màn hình: thêm nhu cầu có vị trí và ảnh, ca sắp tới, ca hôm nay để điểm danh,
-- ca đã qua có điểm danh, chứng chỉ, lịch rảnh, đề xuất kỹ năng, đăng ký tổ chức đang chờ duyệt và thông báo.
-- Chạy sau 03_thu_tuc_va_trigger.sql nên mọi dòng đều đi qua trigger kiểm tra của CSDL.
-- Bộ kiểm thử tự động không nạp tệp này. Toàn bộ là dữ liệu giả; ảnh là hình vẽ minh họa, giấy chứng nhận có chữ BẢN MẪU.
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;

DECLARE @bayGio datetime2(0) = SYSUTCDATETIME();
DECLARE @homNay datetime2(0) = CAST(CAST(@bayGio AS date) AS datetime2(0));
-- Ca hôm nay bắt đầu sau khoảng 30 phút kể từ lúc nạp dữ liệu, kéo dài 4 giờ, để thử điểm danh bằng mã QR.
DECLARE @batDauHomNay datetime2(0) = DATEADD(minute, (DATEDIFF(minute, @homNay, @bayGio) / 5) * 5 + 30, @homNay);

